import Foundation

/// Serves canned data without network access; backs `AppDependencies.preview`.
struct PreviewMovieService: MovieService {
    static let movies: [Movie] = [
        Movie(id: 27205, title: "Inception",
              overview: "A thief who steals corporate secrets through dream-sharing technology.",
              releaseDate: TMDBDate.parse("2010-07-15"), voteAverage: 8.4, voteCount: 35000),
        Movie(id: 157336, title: "Interstellar",
              overview: "A team of explorers travel through a wormhole in space.",
              releaseDate: TMDBDate.parse("2014-11-05"), voteAverage: 8.4, voteCount: 33000),
        Movie(id: 155, title: "The Dark Knight",
              overview: "Batman faces the Joker, a criminal mastermind.",
              releaseDate: TMDBDate.parse("2008-07-16"), voteAverage: 8.5, voteCount: 32000)
    ]

    func popular(page: Int) async throws -> PagedResponse<Movie> {
        try Self.page(Self.movies)
    }

    func search(query: String, page: Int) async throws -> PagedResponse<Movie> {
        let matches = Self.movies.filter { $0.title.localizedCaseInsensitiveContains(query) }
        return try Self.page(matches)
    }

    func detail(id: Int) async throws -> MovieDetail {
        let movie = Self.movies.first { $0.id == id } ?? Self.movies[0]
        return try Self.decode("""
        {"id": \(movie.id), "title": \(Self.quoted(movie.title)), "overview": \(Self.quoted(movie.overview)),
         "release_date": "\(movie.releaseDate.map(TMDBDate.string(from:)) ?? "")",
         "vote_average": \(movie.voteAverage), "vote_count": \(movie.voteCount), "runtime": 148,
         "tagline": "Preview tagline", "genres": [{"id": 28, "name": "Action"}, {"id": 878, "name": "Science Fiction"}],
         "status": "Released"}
        """)
    }

    func credits(id: Int) async throws -> Credits {
        try Self.decode("""
        {"id": \(id),
         "cast": [{"id": 1, "name": "Leonardo DiCaprio", "character": "Cobb", "order": 0}],
         "crew": [{"id": 2, "name": "Christopher Nolan", "job": "Director", "department": "Directing"}]}
        """)
    }

    private static func page(_ results: [Movie]) throws -> PagedResponse<Movie> {
        let data = try JSONEncoder().encode(results)
        let json = #"{"page": 1, "results": \#(String(decoding: data, as: UTF8.self)), "total_pages": 1, "total_results": \#(results.count)}"#
        return try decode(json)
    }

    private static func decode<T: Decodable>(_ json: String) throws -> T {
        try JSONDecoder.tmdb.decode(T.self, from: Data(json.utf8))
    }

    private static func quoted(_ string: String) -> String {
        String(decoding: (try? JSONEncoder().encode(string)) ?? Data("\"\"".utf8), as: UTF8.self)
    }
}
